package com.bankpli.javabank.transfer;
import com.bankpli.javabank.account.*;import com.bankpli.javabank.audit.AuditService;import com.bankpli.javabank.shared.BusinessException;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class TransferService {private final AccountService accounts;private final TransferValidator validator;private final FeeCalculator fees;private final OverdraftService overdraft;private final AuditService audit;public TransferService(AccountService a,TransferValidator v,FeeCalculator f,OverdraftService o,AuditService au){accounts=a;validator=v;fees=f;overdraft=o;audit=au;}@Transactional public TransferResult execute(TransferRequest r){Account from=accounts.find(r.fromAccount(),r.fromSortCode()),to=accounts.find(r.toAccount(),r.toSortCode());if(!from.isActive()||!to.isActive())throw new BusinessException(HttpStatus.CONFLICT,"Both accounts must be active");boolean sameOwner=from.getHolderIds().stream().anyMatch(to.getHolderIds()::contains);validator.validate(r,LocalDate.now(),sameOwner).ifPresent(e->{throw new BusinessException(HttpStatus.BAD_REQUEST,e);});BigDecimal fee=fees.calculate(r.amount(),r.priority(),r.type()),debit=r.amount().add(fee);if(!overdraft.withinLimit(from.getAvailableBalance(),debit,from.getOverdraftLimit()))throw new BusinessException(HttpStatus.CONFLICT,"Insufficient funds and overdraft limit exceeded");from.debit(debit);to.credit(r.amount());audit.append("TRANSFER",r.fromAccount()+" -> "+r.toAccount()+" amount="+r.amount()+" fee="+fee);return new TransferResult("COMPLETED",r.amount(),fee,from.getAvailableBalance(),to.getAvailableBalance(),route(r));}public BigDecimal preview(TransferRequest r){return fees.calculate(r.amount(),r.priority(),r.type());}private List<String> route(TransferRequest r){if(r.type()==TransferType.INTERNAL)return List.of(r.fromAccount(),r.toAccount());return List.of(r.fromAccount(),"INTERMEDIARY",r.toAccount());}}
